"use client";
import { ChevronDown } from "lucide-react";import { useState } from "react";import { useQChatRunState,useQChatMessages,useQChatTools,useQChatLocale } from "../provider/qchat-provider";
export function QChatThinking(){const {reasoning,status}=useQChatRunState();const messages=useQChatMessages();const tools=useQChatTools();const {locale}=useQChatLocale();const [open,setOpen]=useState(false);if(!reasoning)return status==="running"&&!messages.at(-1)?.content.trim()&&tools.length===0?<p className="qchat-waiting" role="status">{locale.direction==="rtl"?"في انتظار الرد":"Waiting for response"}</p>:null;return <section className="qchat-thinking"><button type="button" aria-expanded={open} onClick={()=>setOpen(!open)}><span className={status==="running"?"qchat-waiting":undefined}>{reasoning.label}</span><time>{(reasoning.elapsedMs/1000).toFixed(1)}s</time><ChevronDown size={14} className={open?"is-open":""}/></button>{open&&<p>{reasoning.label}</p>}</section>}
