"use client";
import { Check,ChevronDown,LoaderCircle,Wrench,X } from "lucide-react";import { useState } from "react";import { useQChatTools } from "../provider/qchat-provider";
export function QChatToolActivity(){const tools=useQChatTools();const [open,setOpen]=useState(false);if(!tools.length)return null;return <section className="qchat-tools"><button type="button" aria-expanded={open} onClick={()=>setOpen(!open)}><Wrench size={14}/><span>{tools.length} tool {tools.length===1?"call":"calls"}</span><ChevronDown size={14} className={open?"is-open":""}/></button>{open&&<ul>{tools.map((tool)=><li key={tool.id}>{tool.status==="running"?<LoaderCircle className="spin" size={14}/>:tool.status==="complete"?<Check size={14}/>:<X size={14}/>}<div><strong>{tool.name}</strong>{tool.summary&&<span>{tool.summary}</span>}</div></li>)}</ul>}</section>}
